<?php get_header(); ?><main class="dn-wrap dn-hero"><h1><?php post_type_archive_title(); ?></h1><p>Browse the latest affiliate picks.</p></main><div class="dn-wrap dn-main"><aside class="dn-side"><h3>Categories</h3><?php $terms=get_terms(array('taxonomy'=>'product_category','hide_empty'=>true)); foreach($terms as $term) echo '<a href="'.esc_url(get_term_link($term)).'">'.esc_html($term->name).'</a>'; ?></aside><section><div class="dn-grid"><?php if(have_posts()):while(have_posts()):the_post();get_template_part('template-parts/product-card');endwhile;the_posts_pagination();else:echo '<p>No products found.</p>';endif; ?></div></section></div><?php get_footer(); ?>
